<?php
/*
 * INSTALADOR INTIPATH - ARREGLO (admin/index.php)
 * Sube ESTE UNICO archivo a public_html/ y abre en tu navegador:
 *   https://www.intipathtours.com/instalador.php?token=INTIPATH2026
 * Escribe por si mismo todos los archivos en sus carpetas correctas.
 * Cuando diga TODO OK, BORRA este archivo del servidor.
 */
error_reporting(E_ALL);
ini_set('display_errors', '1');

if (PHP_SAPI !== 'cli' && (!isset($_GET['token']) || $_GET['token'] !== 'INTIPATH2026')) {
    http_response_code(403);
    exit('Acceso denegado: token invalido.');
}

$archivos = array(
  'admin/index.php' => '',
);

echo "<pre>";
echo "=== INSTALADOR INTIPATH ===\n\n";
$ok = 0;
$fallas = array();
foreach ($archivos as $ruta => $b64) {
    $destino = __DIR__ . '/' . $ruta;
    $dir = dirname($destino);
    if (!is_dir($dir)) {
        if (!@mkdir($dir, 0755, true)) {
            $fallas[] = $ruta . " (no se pudo crear $dir)";
            continue;
        }
    }
    $contenido = base64_decode($b64);
    if (@file_put_contents($destino, $contenido) === false) {
        $fallas[] = $ruta;
        continue;
    }
    $ok++;
    echo "OK   " . $ruta . " (" . strlen($contenido) . " bytes)\n";
}
echo "\nInstalados: $ok de " . count($archivos) . "\n";
if (count($fallas) > 0) {
    echo "\nFALLARON:\n" . implode("\n", $fallas) . "\n";
} else {
    echo "TODO OK. Borra este archivo (instalador.php) del servidor.\n";
}
echo "</pre>";